from typing import Callable, Sequence


def comp_retention(deltas: Sequence[float]) -> float:
    r = 1.0
    for d in deltas:
        r *= 1.0 - d
    return r


def depth_knee(deficits: Callable[[int], Sequence[float]], g: float, kmax: int = 10**7) -> int:
    """Smallest k with prod_l (1 - delta_l(k)) >= g; deficits must be non-increasing in k."""
    lo, hi = 0, kmax
    while lo < hi:
        mid = (lo + hi) // 2
        if comp_retention(deficits(mid)) >= g:
            hi = mid
        else:
            lo = mid + 1
    return lo


def sandwich_window(d: int, c: float, g: float) -> tuple[float, int]:
    """Closed-form window [g d c/(1-g) - c, ceil(d c/(1-g))] for the toy knee."""
    import math
    return g * d * c / (1 - g) - c, math.ceil(d * c / (1 - g))


def collapsed_bound(m: int, c: float, g: float, k0: int) -> int:
    import math
    return max(k0, math.ceil(m * c / (1 - g)))


if __name__ == "__main__":
    c, g = 0.2, 0.98
    for d in (12, 24, 48):
        k = depth_knee(lambda k: [c / (c + k)] * d, g)
        print(d, k, sandwich_window(d, c, g), collapsed_bound(2, c, g, 12))

from typing import Sequence


def kstar(w: Sequence[float], n: int, tau: float) -> int:
    """Knee of a sorted profile at context n: one prefix-sum pass, O(n)."""
    H = sum(w[:n])
    s = 0.0
    for k in range(n + 1):
        if s >= tau * H:
            return k
        s += w[k]
    return n


def knee_sequence(w: Sequence[float], contexts: Sequence[int], tau: float) -> list[int]:
    ks = [kstar(w, n, tau) for n in contexts]
    assert all(a <= b for a, b in zip(ks, ks[1:])), "monotonicity violated"
    return ks


def geometric_uniform_bound(r: float, tau: float) -> int:
    """Smallest B with r^B/(1-r) <= 1 - tau: a context-free ceiling on the knee."""
    B = 0
    while r ** B / (1 - r) > 1 - tau:
        B += 1
    return B


def certified_bracket(sweep: Sequence[tuple[int, float]], tau: float) -> tuple[int, int]:
    """Largest failing and smallest passing budget of a grid sweep: k* in (lo, hi]."""
    fails = [k for k, r in sweep if r < tau]
    passes = [k for k, r in sweep if r >= tau]
    return (max(fails) if fails else 0, min(passes))


if __name__ == "__main__":
    w = [0.85 ** i for i in range(8192)]
    print(knee_sequence(w, [64, 256, 1024, 4096, 8192], 0.98), geometric_uniform_bound(0.85, 0.98))
    print(certified_bracket([(16, 0.9771), (32, 0.9912)], 0.98),
          certified_bracket([(16, 0.9708), (24, 0.9818)], 0.98))

import math
from typing import Sequence


def selection_gap(w: Sequence[float], n: int, k: int) -> float:
    ws = sorted(w[:n], reverse=True)
    return sum(ws[:k]) / sum(ws) - k / n


def band_gap_bound(n: int, k: int, c: float, M: float) -> float:
    return k * (M - c) / (n * c)


def knee_gap_lower(n: int, kstar: int, tau: float) -> float:
    return tau - kstar / n


def effective_support(p: Sequence[float]) -> float:
    return 1.0 / sum(x * x for x in p)


def mass_ceiling(k: int, n_eff: float) -> float:
    """Cauchy-Schwarz: any k keys carry at most sqrt(k / N_eff) of the mass."""
    return min(1.0, math.sqrt(k / n_eff))


def mass_knee_floor(rho: float, n_eff: float) -> int:
    """Any key set with mass >= rho has at least ceil(rho^2 N_eff) keys."""
    return math.ceil(rho * rho * n_eff - 1e-12)


if __name__ == "__main__":
    print(knee_gap_lower(2048, 24, 0.98), band_gap_bound(2048, 24, 1.0, 2.0))
    print(mass_ceiling(24, 128.5), mass_knee_floor(0.98, 12))
